// Compute common boundary edges directly on the final BRep solids, including cuts and holes.
// No edge is a weld instruction until explicitly selected and approved.
export function kernelContact(oc,makePart,parts,pairs,onProgress=()=>{}){const byId=new Map(parts.map(p=>[p.id,p])),shapes=new Map,results=[];const tol=.001;try{for(const [index,pair] of pairs.entries()){const a=byId.get(pair[0]),b=byId.get(pair[1]);if(!a||!b||a===b)throw Error('זוג חלקים לא תקין');let owned=[];const own=x=>(owned.push(x),x);try{for(const p of [a,b])if(!shapes.has(p.id))shapes.set(p.id,makePart(p));const x=shapes.get(a.id),y=shapes.get(b.id),common=own(new oc.BRepAlgoAPI_Common(x.wrapped,y.wrapped,own(new oc.Message_ProgressRange)));if(!common.IsDone())throw Error('חישוב חפיפה נכשל');const commonShape=own(common.Shape()),props=own(new oc.GProp_GProps);if(!commonShape.IsNull())oc.BRepGProp.VolumeProperties(commonShape,props,false,false,false);const overlap=Math.abs(props.Mass());if(overlap>tol){results.push({pair,overlap,edges:[],status:'overlap'});continue;}const section=own(new oc.BRepAlgoAPI_Section(x.wrapped,y.wrapped,true));if(!section.IsDone())throw Error('חישוב קווי מגע נכשל');const shape=own(section.Shape()),edges=[];if(!shape.IsNull()){const explorer=own(new oc.TopExp_Explorer(shape,oc.TopAbs_ShapeEnum.TopAbs_EDGE,oc.TopAbs_ShapeEnum.TopAbs_SHAPE));while(explorer.More()){const raw=own(explorer.Current()),edge=own(oc.TopoDS.Edge(raw)),g=own(new oc.GProp_GProps);oc.BRepGProp.LinearProperties(edge,g,true,false);const length=g.Mass();if(length>tol){const curve=own(new oc.BRepAdaptor_Curve(edge)),from=curve.FirstParameter(),to=curve.LastParameter(),line=curve.GetType()===oc.GeomAbs_CurveType.GeomAbs_Line,n=line?1:Math.max(8,Math.min(128,Math.ceil(length/2))),points=[];for(let i=0;i<=n;i++){const p=own(curve.Value(from+(to-from)*i/n));points.push([p.X(),p.Y(),p.Z()].map(v=>+v.toFixed(6)));}const aKey=JSON.stringify(points),bKey=JSON.stringify([...points].reverse()),key=aKey<bKey?aKey:bKey;edges.push({key,length:+length.toFixed(6),points,curve:line?'line':'curve'});}explorer.Next();}}
const unique=[...new Map(edges.map(e=>[e.key,e])).values()].sort((a,b)=>a.key.localeCompare(b.key)).map((e,i)=>({...e,id:i+1}));results.push({pair,overlap,edges:unique,status:unique.length?'proposal':'no-contact'});
}finally{onProgress(index+1,pairs.length);for(const a of owned.reverse())try{a.delete()}catch{}}}return results;}finally{for(const x of shapes.values())try{x.delete()}catch{}}}
